-// Helper function to show time elapsed - FIXED the DateInterval error
-function time_elapsed_string($datetime, $full = false) {
-    if (empty($datetime)) {
-        return 'just now';
-    }
-    
-    $now = new DateTime();
-    $ago = new DateTime($datetime);
-    $diff = $now->diff($ago);
-    
-    // Calculate weeks manually (since DateInterval::$w doesn't exist in all PHP versions)
-    $diff->w = floor($diff->d / 7);
-    $diff->d -= $diff->w * 7;
-    
-    $string = array(
-        'y' => 'year',
-        'm' => 'month',
-        'w' => 'week',
-        'd' => 'day',
-        'h' => 'hour',
-        'i' => 'minute',
-        's' => 'second',
-    );
-    
-    $has_value = false;
-    foreach ($string as $k => &$v) {
-        if ($diff->$k) {
-            $v = $diff->$k . ' ' . $v . ($diff->$k > 1 ? 's' : '');
-            $has_value = true;
-        } else {
-            unset($string[$k]);
-        }
-    }
-    
-    if (!$has_value) {
-        return 'just now';
-    }
-    
-    if (!$full) {
-        $string = array_slice($string, 0, 1);
-    }
-    return implode(', ', $string) . ' ago';
-}
