+function time_elapsed_string($datetime, $full = false) {
+    if (empty($datetime)) return 'just now';
+    $now = new DateTime();
+    $ago = new DateTime($datetime);
+    $diff = $now->diff($ago);
+    
+    // Create array from DateInterval properties (DateInterval properties are read-only)
+    $diff_array = array(
+        'y' => $diff->y,
+        'm' => $diff->m,
+        'd' => $diff->d,
+        'h' => $diff->h,
+        'i' => $diff->i,
+        's' => $diff->s
+    );
+    
+    // Calculate weeks and adjust days
+    $diff_array['w'] = floor($diff_array['d'] / 7);
+    $diff_array['d'] -= $diff_array['w'] * 7;
+    
+    $string = array('y' => 'year', 'm' => 'month', 'w' => 'week', 'd' => 'day', 'h' => 'hour', 'i' => 'minute', 's' => 'second');
+    $has_value = false;
+    foreach ($string as $k => &$v) {
+        if ($diff_array[$k]) {
+            $v = $diff_array[$k] . ' ' . $v . ($diff_array[$k] > 1 ? 's' : '');
+            $has_value = true;
+        } else {
+            unset($string[$k]);
+        }
+    }
+    if (!$has_value) return 'just now';
+    if (!$full) $string = array_slice($string, 0, 1);
+    return implode(', ', $string) . ' ago';
+}
